{{ config(materialized = 'ephemeral') }}

-- LIGHTBOX -> property_address: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: STTM business keys.

with sp_property_address as (
    select
        upper(trim(o.ASSESSMENT_LID)) as source_unique_id,
        nullif(trim(o.COUNTY), '') as county,
        nullif(trim(o.FIPS_CODE), '') as source_county,
        nullif(trim(o.GEOMETRY), '') as geometry
    from {{ source('property_address_lightbox_source', 'assessment') }} as o
    where nullif(upper(trim(o.ASSESSMENT_LID)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ASSESSMENT_LID)) order by source_unique_id) = 1
),

ref_source_system as (
    {{ m_get_source_system_skey_property('LIGHTBOX') }}
),

base as (
    select
        o.source_unique_id,
        r.gdp_source_system_skey as ref_gdp_source_system_skey,
        hub.property_core_skey as property_core_skey,
        null as ref_address_type_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_ADDRESS_TYPE_SKEY */,
        null as address_line_1,
        null as address_line_2,
        null as street_name,
        null as street_number_1,
        null as street_number_2,
        null as pre_street_direction_name,
        null as street_type,
        null as post_street_direction_name,
        null as city,
        null as state_province,
        null as country,
        o.county as county,
        null as postal_code,
        null as state,
        null as postal_code_extension,
        null as street_number_3,
        null as latitude,
        null as longitude,
        null as source_address_line_1,
        null as source_address_line_2,
        null as source_street_name,
        null as source_street_number_1,
        null as source_street_number_2,
        null as source_pre_street_direction_name,
        null as source_street_type,
        null as source_post_street_direction_name,
        null as source_city,
        o.source_county as source_county,
        null as source_state,
        null as source_postal_code,
        null as source_postal_code_extension,
        null as source_country_name,
        null as source_street_number_3,
        null as source_geocode_output,
        null as source_latitude,
        null as source_longitude,
        null as source_latitude_override,
        null as source_longitude_override,
        null as source_geocode_override_source,
        null as address_match_score,
        null as address_match_code,
        null as geocode_output,
        null as address_precision_code,
        null as geocode_provider_name,
        o.geometry as geometry,
        true as gdp_is_active,
        current_timestamp()::timestamp_ntz as gdp_inserted_ts,
        current_user() as gdp_inserted_by,
        current_timestamp()::timestamp_ntz as gdp_updated_ts,
        current_user() as gdp_updated_by,
        null as source_street_name_pre_type,
        null as street_name_pre_type,
        null as country_iso2_code,
        null as country_iso3_code,
        null as state_iso_code
    from sp_property_address as o
    cross join ref_source_system as r
    left join (
        select source_unique_id, property_core_skey
        from {{ ref('property_core') }}
        where gdp_is_active
        qualify row_number() over (partition by source_unique_id order by gdp_inserted_ts desc) = 1
    ) as hub
        on hub.source_unique_id = o.source_unique_id
)

select
    {{ this.schema }}.seq_property_address_skey.nextval as property_address_skey,
    source_unique_id,
    ref_gdp_source_system_skey,
    property_core_skey,
    ref_address_type_skey,
    address_line_1,
    address_line_2,
    street_name,
    street_number_1,
    street_number_2,
    pre_street_direction_name,
    street_type,
    post_street_direction_name,
    city,
    state_province,
    country,
    county,
    postal_code,
    state,
    postal_code_extension,
    street_number_3,
    latitude,
    longitude,
    source_address_line_1,
    source_address_line_2,
    source_street_name,
    source_street_number_1,
    source_street_number_2,
    source_pre_street_direction_name,
    source_street_type,
    source_post_street_direction_name,
    source_city,
    source_county,
    source_state,
    source_postal_code,
    source_postal_code_extension,
    source_country_name,
    source_street_number_3,
    source_geocode_output,
    source_latitude,
    source_longitude,
    source_latitude_override,
    source_longitude_override,
    source_geocode_override_source,
    address_match_score,
    address_match_code,
    geocode_output,
    address_precision_code,
    geocode_provider_name,
    geometry,
    {{ m_property_address_hkey() }} as property_address_hkey,
    gdp_is_active,
    gdp_inserted_ts,
    gdp_inserted_by,
    gdp_updated_ts,
    gdp_updated_by,
    source_street_name_pre_type,
    street_name_pre_type,
    country_iso2_code,
    country_iso3_code,
    state_iso_code
from base
